const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n }, () => []);
for (let i = 0; i < m; i++) {
  const u = tok[2 + 2 * i] - 1, v = tok[3 + 2 * i] - 1;
  adj[u].push([v, i]); adj[v].push([u, i]);
}
const tin = new Array(n).fill(-1), low = new Array(n).fill(0), isCut = new Array(n).fill(false);
let bridges = 0, timer = 0;
function dfs(u, parentEdge) {
  tin[u] = low[u] = timer++;
  let children = 0;
  for (const [v, eid] of adj[u]) {
    if (eid === parentEdge) continue;
    if (tin[v] >= 0) low[u] = Math.min(low[u], tin[v]);
    else {
      dfs(v, eid);
      low[u] = Math.min(low[u], low[v]);
      if (low[v] > tin[u]) bridges++;
      if (parentEdge !== -1 && low[v] >= tin[u]) isCut[u] = true;
      children++;
    }
  }
  if (parentEdge === -1 && children >= 2) isCut[u] = true;
}
for (let u = 0; u < n; u++) if (tin[u] < 0) dfs(u, -1);
