import java.io.*;
import java.util.*;

public class Main {
    static ArrayList<int[]>[] adj;
    static int[] tin, low;
    static boolean[] isCut;
    static int timer = 0, bridges = 0;

    static void dfs(int u, int parentEdge) {
        tin[u] = low[u] = timer++;
        int children = 0;
        for (int[] pr : adj[u]) {
            int v = pr[0], eid = pr[1];
            if (eid == parentEdge) continue;
            if (tin[v] >= 0) {
                low[u] = Math.min(low[u], tin[v]);
            } else {
                dfs(v, eid);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > tin[u]) bridges++;
                if (parentEdge != -1 && low[v] >= tin[u]) isCut[u] = true;
                children++;
            }
        }
        if (parentEdge == -1 && children >= 2) isCut[u] = true;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        Thread t = new Thread(null, () -> {
            try {
                StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
                in.nextToken();
                int n = (int) in.nval;
                in.nextToken();
                int m = (int) in.nval;
                adj = new ArrayList[n];
                for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
                for (int i = 0; i < m; i++) {
                    in.nextToken(); int u = (int) in.nval - 1;
                    in.nextToken(); int v = (int) in.nval - 1;
                    adj[u].add(new int[]{v, i});
                    adj[v].add(new int[]{u, i});
                }
                tin = new int[n]; low = new int[n]; isCut = new boolean[n];
                Arrays.fill(tin, -1);
                for (int u = 0; u < n; u++) if (tin[u] < 0) dfs(u, -1);
                int cuts = 0;
                for (boolean b : isCut) if (b) cuts++;
                System.out.println(bridges + " " + cuts);
            } catch (IOException e) { throw new RuntimeException(e); }
        }, "main", 1 << 26);
        t.start();
        t.join();
    }
}

