#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0, bridges = 0;
vector<vector<pair<int,int>>> adj;
vector<int> tin, low;
vector<bool> is_cut;
void dfs(int u, int parent_edge) {
    tin[u] = low[u] = timer_++;
    int children = 0;
    for (auto [v, eid] : adj[u]) {
        if (eid == parent_edge) continue;
        if (tin[v] >= 0) low[u] = min(low[u], tin[v]);
        else {
            dfs(v, eid);
            low[u] = min(low[u], low[v]);
            if (low[v] > tin[u]) bridges++;
            if (parent_edge != -1 && low[v] >= tin[u]) is_cut[u] = true;
            children++;
        }
    }
    if (parent_edge == -1 && children >= 2) is_cut[u] = true;
}
int main() {
    scanf("%d %d", &n, &m);
    adj.assign(n, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        adj[u].push_back({v, i});
        adj[v].push_back({u, i});
    }
    tin.assign(n, -1); low.assign(n, 0); is_cut.assign(n, false);
    for (int u = 0; u < n; u++) if (tin[u] < 0) dfs(u, -1);
    int cuts = 0;
    for (int u = 0; u < n; u++) cuts += is_cut[u];
    printf("%d %d\n", bridges, cuts);
    return 0;
}
